{
  "findings": [
    {
      "check_id": "CKV_GCP_62",
      "title": "Cloud Storage access logging is disabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket has no logging configuration, limiting the ability to investigate unauthorized or suspicious access to compliance data."
    },
    {
      "check_id": "CKV_GCP_29",
      "title": "Uniform bucket-level access is not enabled",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "Without uniform bucket-level access, object ACLs can grant permissions outside the bucket's centralized IAM policy and create inconsistent access controls."
    },
    {
      "check_id": "CKV_GCP_114",
      "title": "Public access prevention is not enforced",
      "resource": "google_storage_bucket.compliance_storage",
      "severity": "MEDIUM",
      "explanation": "The bucket does not explicitly prevent public IAM grants, increasing the risk that compliance data could be exposed through a future policy change."
    }
  ],
  "patched_code": "resource "google_storage_bucket" "compliance_storage" {
  name                       = "${var.project_id}-digital-asset-trading-platform-compliance"
  location                   = var.region
  uniform_bucket_level_access = true
  public_access_prevention    = "enforced"

  logging {
    log_bucket        = "${var.project_id}-digital-asset-trading-platform-compliance"
    log_object_prefix = "access-logs/"
  }

  versioning {
    enabled = true
  }

  lifecycle_rule {
    condition {
      age = 2555
    }
    action {
      type = "Delete"
    }
  }
}

resource "google_storage_bucket_iam_member" "compliance_logging_writer" {
  bucket = google_storage_bucket.compliance_storage.name
  role   = "roles/storage.objectCreator"
  member = "group:cloud-storage-analytics@google.com"
}
",
  "fix_summary": "Enabled uniform bucket-level access and enforced public access prevention. Configured access logs under a dedicated prefix in the protected bucket and granted the Cloud Storage analytics delivery identity permission to create log objects."
}
